def redact(text):
    out = []
    for line in text.split("\n"):
        if "=" in line:
            key, _, value = line.partition("=")
            if key.strip().upper().endswith(("_KEY", "_SECRET", "_TOKEN", "PASSWORD")):
                line = key + "=***"
        out.append(line)
    return "\n".join(out)

